import asyncio
from playwright.async_api import async_playwright

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        page = await browser.new_page(viewport={"width": 4000, "height": 2000})
        await page.goto("http://localhost:8765/output/diagram.html", wait_until="networkidle", timeout=30000)
        await page.wait_for_selector(".mermaid svg", state="visible", timeout=15000)
        await page.wait_for_timeout(2000)

        # Get the container's bounding box (title + legend + diagram)
        bbox = await page.evaluate("""
            () => {
                const container = document.querySelector('.container');
                if (!container) return null;
                const rect = container.getBoundingClientRect();
                return { x: rect.x, y: rect.y, width: rect.width, height: rect.height };
            }
        """)
        print("Container bbox:", bbox)

        if bbox and bbox["width"] > 10 and bbox["height"] > 10:
            await page.screenshot(
                path="/app/output/result.png",
                clip={
                    "x": max(0, int(bbox["x"]) - 24),
                    "y": max(0, int(bbox["y"]) - 24),
                    "width": int(bbox["width"]) + 48,
                    "height": int(bbox["height"]) + 48,
                }
            )
        else:
            await page.screenshot(path="/app/output/result.png", full_page=True)

        await browser.close()

asyncio.run(main())
